#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Embeddált sshd (port 2230) kulcsrotáció automatizálása.
Napi cron ellenőrzi a host-kulcsok lejáratát, és CA-ból frissít,
hogy elkerüljük a peer-connect force miatti node-lockoutot.

Használat:
    python3 scripts/sshd_key_rotation.py --check
    python3 scripts/sshd_key_rotation.py --rotate
    python3 scripts/sshd_key_rotation.py --status

Cron bejegyzés (napi 03:00):
    0 3 * * * /usr/bin/python3 /path/to/a2a_mesh/scripts/sshd_key_rotation.py --check >> /var/log/a2a_mesh/key_rotation.log 2>&1
"""

import argparse
import hashlib
import json
import logging
import os
import shutil
import subprocess
import sys
import time
from datetime import datetime, timedelta, timezone
from pathlib import Path

# ---------------------------------------------------------------------------
# Konfiguráció
# ---------------------------------------------------------------------------

REPO_ROOT = Path(__file__).resolve().parent.parent
CONFIG_DIR = REPO_ROOT / "config"
STATE_DIR = REPO_ROOT / "state"
KEY_DIR = Path("/etc/ssh/a2a_mesh")  # embeddált sshd kulcsok könyvtára
CA_KEY_DIR = CONFIG_DIR / "ca"       # CA kulcsok a repón belül
LOG_DIR = Path("/var/log/a2a_mesh")

SSHD_PORT = 2230
SSHD_CONFIG = CONFIG_DIR / "sshd_embedded.conf"
KEY_ROTATION_STATE = STATE_DIR / "key_rotation_state.json"
KEY_ROTATION_LOG = LOG_DIR / "key_rotation.log"

# Rotációs beállítások
DEFAULT_KEY_TTL_DAYS = 30
ROTATION_THRESHOLD_DAYS = 7   # 7 napon belüli lejárat -> rotál
KEY_TYPES = ["rsa", "ed25519", "ecdsa"]
KEY_BITS = {"rsa": 4096, "ecdsa": 521, "ed25519": 256}

# CA beállítások
CA_HOST_KEY = CA_KEY_DIR / "ca_host_key"
CA_HOST_PUB = CA_KEY_DIR / "ca_host_key.pub"

# Peer értesítés
PEER_NOTIFY_SCRIPT = REPO_ROOT / "scripts" / "notify_peers.py"
MESH_STATE_FILE = STATE_DIR / "mesh_state.json"

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

def setup_logging():
    LOG_DIR.mkdir(parents=True, exist_ok=True)
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    CA_KEY_DIR.mkdir(parents=True, exist_ok=True)

    logger = logging.getLogger("sshd_key_rotation")
    logger.setLevel(logging.DEBUG)

    # File handler
    fh = logging.FileHandler(KEY_ROTATION_LOG)
    fh.setLevel(logging.DEBUG)
    fh.setFormatter(logging.Formatter(
        "%(asctime)s [%(levelname)s] %(message)s"
    ))
    logger.addHandler(fh)

    # Console handler
    ch = logging.StreamHandler()
    ch.setLevel(logging.INFO)
    ch.setFormatter(logging.Formatter("[%(levelname)s] %(message)s"))
    logger.addHandler(ch)

    return logger

log = setup_logging()

# ---------------------------------------------------------------------------
# Állapotkezelés
# ---------------------------------------------------------------------------

def load_state() -> dict:
    if KEY_ROTATION_STATE.exists():
        try:
            return json.loads(KEY_ROTATION_STATE.read_text())
        except (json.JSONDecodeError, IOError):
            log.warning("State file corrupt or unreadable, starting fresh.")
    return {
        "keys": {},
        "last_rotation": None,
        "last_check": None,
        "rotation_count": 0,
        "ca_fingerprint": None,
    }

def save_state(state: dict):
    KEY_ROTATION_STATE.parent.mkdir(parents=True, exist_ok=True)
    tmp = KEY_ROTATION_STATE.with_suffix(".tmp")
    tmp.write_text(json.dumps(state, indent=2, default=str))
    tmp.replace(KEY_ROTATION_STATE)
    log.debug("State saved to %s", KEY_ROTATION_STATE)

# ---------------------------------------------------------------------------
# CA kezelés
# ---------------------------------------------------------------------------

def ensure_ca_exists() -> bool:
    """Biztosítja, hogy a CA host-kulcs létezik. Ha nem, generálja."""
    if CA_HOST_KEY.exists() and CA_HOST_PUB.exists():
        log.debug("CA host key exists at %s", CA_HOST_KEY)
        return True

    log.info("CA host key not found, generating new CA key pair...")
    CA_KEY_DIR.mkdir(parents=True, exist_ok=True)

    cmd = [
        "ssh-keygen", "-t", "ed25519",
        "-f", str(CA_HOST_KEY),
        "-C", "a2a_mesh_ca_host",
        "-N", "",  # no passphrase (automatizált környezet)
    ]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        if result.returncode != 0:
            log.error("CA key generation failed: %s", result.stderr)
            return False
        log.info("CA host key generated successfully.")
        return True
    except FileNotFoundError:
        log.error("ssh-keygen not found. Please install openssh-server.")
        return False
    except subprocess.TimeoutExpired:
        log.error("CA key generation timed out.")
        return False

def get_ca_fingerprint() -> str:
    if not CA_HOST_PUB.exists():
        return ""
    try:
        result = subprocess.run(
            ["ssh-keygen", "-lf", str(CA_HOST_PUB)],
            capture_output=True, text=True, timeout=10
        )
        if result.returncode == 0:
            # "256 SHA256:xxx a2a_mesh_ca_host (ED25519)"
            parts = result.stdout.strip().split()
            if len(parts) >= 2:
                return parts[1]
    except Exception as e:
        log.warning("Could not get CA fingerprint: %s", e)
    return ""

# ---------------------------------------------------------------------------
# Kulcskezelés
# ---------------------------------------------------------------------------

def get_key_path(key_type: str, suffix: str = "") -> Path:
    name = f"ssh_host_{key_type}_key{suffix}"
    return KEY_DIR / name

def get_key_pub_path(key_type: str, suffix: str = "") -> Path:
    return get_key_path(key_type, suffix).with_suffix(".pub")

def generate_host_key(key_type: str) -> Path | None:
    """Generál egy új host kulcsot a megadott típusból."""
    KEY_DIR.mkdir(parents=True, exist_ok=True)

    key_path = get_key_path(key_type, "_new")
    bits = KEY_BITS.get(key_type, 4096)

    cmd = ["ssh-keygen", "-t", key_type, "-f", str(key_path), "-N", "",
           "-C", f"a2a_mesh_host_{key_type}_{int(time.time())}"]

    if key_type in ("rsa", "ecdsa"):
        cmd.extend(["-b", str(bits)])

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=60)
        if result.returncode != 0:
            log.error("Failed to generate %s key: %s", key_type, result.stderr)
            return None
        log.debug("Generated new %s key at %s", key_type, key_path)
        return key_path
    except Exception as e:
        log.error("Key generation error for %s: %s", key_type, e)
        return None

def sign_key_with_ca(key_pub_path: Path, key_type: str) -> Path | None:
    """Aláírja a host kulcsot a CA-val, generál egy certificate-et."""
    if not ensure_ca_exists():
        log.error("CA not available, cannot sign key.")
        return None

    cert_path = key_pub_path.with_suffix("-cert.pub")
    principals = "a2a-mesh,node,localhost"

    # Host certificate: -h flag
    cmd = [
        "ssh-keygen", "-s", str(CA_HOST_KEY),
        "-I", f"a2a_mesh_host_{key_type}_{int(time.time())}",
        "-h",  # host certificate
        "-n", principals,
        "-V", f"-5m:+{DEFAULT_KEY_TTL_DAYS}d",  # valid 5 min ago, expires in TTL days
        str(key_pub_path)
    ]

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        if result.returncode != 0:
            log.error("CA signing failed for %s: %s", key_type, result.stderr)
            return None
        log.info("Signed %s key with CA, cert: %s", key_type, cert_path)
        return cert_path
    except Exception as e:
        log.error("CA signing error: %s", e)
        return None

def get_cert_expiry(cert_path: Path) -> datetime | None:
    """Lekéri a certificate lejárati dátumát."""
    if not cert_path.exists():
        return None
    try:
        result = subprocess.run(
            ["ssh-keygen", "-Lf", str(cert_path)],
            capture_output=True, text=True, timeout=10
        )
        if result.returncode != 0:
            return None
        # Parse output for "Valid: from ... to ..."
        for line in result.stdout.splitlines():
            line = line.strip()
            if line.startswith("Valid:"):
                # "Valid: from 2024-01-01T00:00:00 to 2024-01-31T00:00:00"
                parts = line.split(" to ")
                if len(parts) == 2:
                    expiry_str = parts[1].strip()
                    try:
                        return datetime.fromisoformat(expiry_str).replace(tzinfo=timezone.utc)
                    except ValueError:
                        # Try different format
                        try:
                            return datetime.strptime(expiry_str, "%Y-%m-%dT%H:%M:%S").replace(tzinfo=timezone.utc)
                        except ValueError:
                            pass
    except Exception as e:
        log.warning("Could not parse cert expiry: %s", e)
    return None

def get_key_fingerprint(pub_path: Path) -> str:
    if not pub_path.exists():
        return ""
    try:
        result = subprocess.run(
            ["ssh-keygen", "-lf", str(pub_path)],
            capture_output=True, text=True, timeout=10
        )
        if result.returncode == 0:
            parts = result.stdout.strip().split()
            if len(parts) >= 2:
                return parts[1]
    except Exception:
        pass
    return ""

def install_key(key_type: str, new_key_path: Path, new_cert_path: Path) -> bool:
    """Telepíti az új kulcsot és cert-et a helyükre (atomikus cserével)."""
    final_key = get_key_path(key_type)
    final_pub = get_key_pub_path(key_type)
    final_cert = final_pub.with_suffix("-cert.pub")

    try:
        # Backup régi kulcsok
        if final_key.exists():
            backup = final_key.with_suffix(".bak")
            shutil.copy2(final_key, backup)
        if final_pub.exists():
            backup_pub = final_pub.with_suffix(".bak")
            shutil.copy2(final_pub, backup_pub)

        # Atomikus csere
        shutil.move(str(new_key_path), str(final_key))
        shutil.move(str(new_key_path.with_suffix(".pub")), str(final_pub))
        shutil.move(str(new_cert_path), str(final_cert))

        # Jogosultságok
        os.chmod(final_key, 0o600)
        os.chmod(final_pub, 0o644)
        os.chmod(final_cert, 0o644)

        log.info("Installed %s key and cert.", key_type)
        return True
    except Exception as e:
        log.error("Failed to install %s key: %s", key_type, e)
        return False

def reload_sshd() -> bool:
    """Újratölti az sshd-t, hogy felvegye az új kulcsokat."""
    # Próbáljuk systemctl-t, majd fallback kill -HUP
    try:
        result = subprocess.run(
            ["systemctl", "reload", "ssh"],
            capture_output=True, text=True, timeout=15
        )
        if result.returncode == 0:
            log.info("sshd reloaded via systemctl.")
            return True
        log.warning("systemctl reload failed: %s, trying alternative...", result.stderr)
    except FileNotFoundError:
        log.warning("systemctl not found, trying alternative reload...")
    except Exception as e:
        log.warning("systemctl reload error: %s", e)

    # Fallback: find sshd pid and send HUP
    try:
        result = subprocess.run(
            ["pgrep", "-f", "sshd.*2230"],
            capture_output=True, text=True, timeout=10
        )
        if result.returncode == 0 and result.stdout.strip():
            pids = result.stdout.strip().split()
            for pid in pids:
                subprocess.run(["kill", "-HUP", pid], timeout=10)
            log.info("sshd reloaded via SIGHUP (pid: %s).", ", ".join(pids))
            return True
        log.warning("No sshd process found for port 2230.")
        return True  # Nem kritikus, lehet hogy még nem fut
    except Exception as e:
        log.error("Failed to reload sshd: %s", e)
        return False

# ---------------------------------------------------------------------------
# Rotációs logika
# ---------------------------------------------------------------------------

def check_key_expiration(state: dict) -> list[dict]:
    """Ellenőrzi az összes kulcs lejárati állapotát. Visszaadja a rotálandókat."""
    now = datetime.now(timezone.utc)
    threshold = now + timedelta(days=ROTATION_THRESHOLD_DAYS)
    needs_rotation = []

    for key_type in KEY_TYPES:
        cert_path = get_key_pub_path(key_type).with_suffix("-cert.pub")
        key_state = state["keys"].get(key_type, {})

        if not cert_path.exists():
            log.warning("No cert found for %s, needs rotation.", key_type)
            needs_rotation.append({
                "type": key_type,
                "reason": "missing_cert",
                "expiry": None,
            })
            continue

        expiry = get_cert_expiry(cert_path)
        if expiry is None:
            log.warning("Could not determine expiry for %s cert, needs rotation.", key_type)
            needs_rotation.append({
                "type": key_type,
                "reason": "unknown_expiry",
                "expiry": None,
            })
            continue

        days_left = (expiry - now).days
        key_state["expiry"] = expiry.isoformat()
        key_state["days_left"] = days_left
        key_state["fingerprint"] = get_key_fingerprint(get_key_pub_path(key_type))
        state["keys"][key_type] = key_state

        if expiry <= threshold:
            log.info("Key %s expires in %d days (threshold: %d), needs rotation.",
                     key_type, days_left, ROTATION_THRESHOLD_DAYS)
            needs_rotation.append({
                "type": key_type,
                "reason": "expiring",
                "expiry": expiry.isoformat(),
                "days_left": days_left,
            })
        else:
            log.debug("Key %s OK, %d days left.", key_type, days_left)

    return needs_rotation

def rotate_keys(keys_to_rotate: list[dict], state: dict) -> bool:
    """Rotálja a megadott kulcsokat."""
    if not keys_to_rotate:
        log.info("No keys need rotation.")
        return True

    if not ensure_ca_exists():
        log.error("CA not available, cannot rotate keys.")
        return False

    all_success = True
    rotated_types = []

    for key_info in keys_to_rotate:
        key_type = key_info["type"]
        log.info("Rotating %s key (reason: %s)...", key_type, key_info["reason"])

        # 1. Generálj új kulcsot
        new_key = generate_host_key(key_type)
        if new_key is None:
            all_success = False
            continue

        new_pub = new_key.with_suffix(".pub")

        # 2. Írd alá CA-val
        new_cert = sign_key_with_ca(new_pub, key_type)
        if new_cert is None:
            all_success = False
            # Cleanup
            new_key.unlink(missing_ok=True)
            new_pub.unlink(missing_ok=True)
            continue

        # 3. Telepítsd
        if not install_key(key_type, new_key, new_cert):
            all_success = False
            continue

        # 4. Frissítsd az állapotot
        expiry = get_cert_expiry(new_cert)
        state["keys"][key_type] = {
            "installed_at": datetime.now(timezone.utc).isoformat(),
            "expiry": expiry.isoformat() if expiry else None,
            "fingerprint": get_key_fingerprint(get_key_pub_path(key_type)),
            "cert_fingerprint": get_key_fingerprint(new_cert),
            "rotation_reason": key_info["reason"],
        }
        rotated_types.append(key_type)

    # 5. Reload sshd
    if rotated_types:
        if reload_sshd():
            log.info("sshd reloaded with new keys: %s", ", ".join(rotated_types))
        else:
            log.error("sshd reload failed! Keys installed but not active.")
            all_success = False

    # 6. Állapot frissítése
    state["last_rotation"] = datetime.now(timezone.utc).isoformat()
    state["rotation_count"] = state.get("rotation_count", 0) + len(rotated_types)
    state["ca_fingerprint"] = get_ca_fingerprint()

    # 7. Peer értesítés
    if rotated_types:
        notify_peers(rotated_types, state)

    return all_success

# ---------------------------------------------------------------------------
# Peer értesítés
# ---------------------------------------------------------------------------

def load_mesh_state() -> dict:
    if MESH_STATE_FILE.exists():
        try:
            return json.loads(MESH_STATE_FILE.read_text())
        except (json.JSONDecodeError, IOError):
            pass
    return {"peers": [], "node_id": "runa", "node_name": "runa"}

def notify_peers(rotated_types: list[str], state: dict):
    """Értesíti a peer-eket a kulcscseréről, hogy ne kelljen peer-connect force."""
    mesh = load_mesh_state()
    peers = mesh.get("peers", [])
    node_id = mesh.get("node_id", "unknown")

    notification = {
        "type": "key_rotation_notification",
        "node_id": node_id,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "rotated_keys": rotated_types,
        "ca_fingerprint": state.get("ca_fingerprint", ""),
        "sshd_port": SSHD_PORT,
        "message": f"Node {node_id} rotated sshd host keys: {', '.join(rotated_types)}. "
                   f"CA-signed certs updated. No peer-connect force needed.",
    }

    # Mentés a state-be, hogy a peer-connect modul fel tudja dolgozni
    notifications_file = STATE_DIR / "pending_peer_notifications.json"
    notifications = []
    if notifications_file.exists():
        try:
            notifications = json.loads(notifications_file.read_text())
        except (json.JSONDecodeError, IOError):
            notifications = []
    notifications.append(notification)
    notifications_file.write_text(json.dumps(notifications, indent=2, default=str))

    log.info("Peer notification queued for %d peers (keys: %s).",
             len(peers), ", ".join(rotated_types))

    # Ha van notify_peers.py script, hívd meg
    if PEER_NOTIFY_SCRIPT.exists():
        try:
            subprocess.run(
                ["python3", str(PEER_NOTIFY_SCRIPT), "--type", "key_rotation"],
                capture_output=True, text=True, timeout=30
            )
            log.debug("Called notify_peers.py script.")
        except Exception as e:
            log.warning("Could not call notify_peers.py: %s", e)

# ---------------------------------------------------------------------------
# SSHd config frissítés
# ---------------------------------------------------------------------------

def ensure_sshd_config_has_certs():
    """Biztosítja, hogy az sshd config tartalmazza a HostCertificate sorokat."""
    if not SSHD_CONFIG.exists():
        log.warning("sshd config not found at %s, skipping config check.", SSHD_CONFIG)
        return

    content = SSHD_CONFIG.read_text()
    modified = False

    for key_type in KEY_TYPES:
        cert_line = f"HostCertificate {KEY_DIR}/ssh_host_{key_type}_key-cert.pub"
        if cert_line not in content:
            content += f"\n{cert_line}\n"
            modified = True
            log.info("Added HostCertificate line for %s to sshd config.", key_type)

    if modified:
        SSHD_CONFIG.write_text(content)
        log.info("sshd config updated with HostCertificate entries.")

# ---------------------------------------------------------------------------
# Státusz riport
# ---------------------------------------------------------------------------

def print_status(state: dict):
    """Kiírja a kulcsok jelenlegi státuszát."""
    print("\n" + "=" * 60)
    print("  A2A Mesh SSHd Key Rotation Status")
    print("=" * 60)
    print(f"  SSHd Port:        {SSHD_PORT}")
    print(f"  Key Directory:    {KEY_DIR}")
    print(f"  CA Key:           {CA_HOST_KEY}")
    print(f"  CA Fingerprint:   {state.get('ca_fingerprint', 'N/A')}")
    print(f"  Last Check:       {state.get('last_check', 'Never')}")
    print(f"  Last Rotation:    {state.get('last_rotation', 'Never')}")
    print(f"  Rotation Count:   {state.get('rotation_count', 0)}")
    print(f"  TTL:              {DEFAULT_KEY_TTL_DAYS} days")
    print(f"  Threshold:        {ROTATION_THRESHOLD_DAYS} days before expiry")
    print("-" * 60)

    now = datetime.now(timezone.utc)
    for key_type in KEY_TYPES:
        key_state = state["keys"].get(key_type, {})
        expiry_str = key_state.get("expiry", "N/A")
        fp = key_state.get("fingerprint", "N/A")

        if expiry_str and expiry_str != "N/A":
            try:
                expiry = datetime.fromisoformat(expiry_str)
                days_left = (expiry - now).days
                status = "OK" if days_left > ROTATION_THRESHOLD_DAYS else "EXPIRING SOON"
                if days_left < 0:
                    status = "EXPIRED!"
            except ValueError:
                days_left = "?"
                status = "UNKNOWN"
        else:
            days_left = "?"
            status = "MISSING"

        print(f"\n  Key Type:     {key_type}")
        print(f"    Status:     {status}")
        print(f"    Expiry:     {expiry_str}")
        print(f"    Days Left:  {days_left}")
        print(f"    Fingerprint:{fp}")

    print("\n" + "=" * 60 + "\n")

# ---------------------------------------------------------------------------
# Fő logika
# ---------------------------------------------------------------------------

def run_check(force: bool = False) -> int:
    """Napi ellenőrzés: megnézi a lejáratot és rotál ha kell."""
    log.info("=== Daily key rotation check started ===")

    state = load_state()
    state["last_check"] = datetime.now(timezone.utc).isoformat()

    # Biztosítsuk a CA-t
    if not ensure_ca_exists():
        log.error("CA setup failed, aborting.")
        save_state(state)
        return 1

    # Biztosítsuk a config-ban a cert sorokat
    ensure_sshd_config_has_certs()

    # Ellenőrizzük a lejáratot
    needs_rotation = check_key_expiration(state)

    if force:
        log.info("Force rotation requested, rotating all keys.")
        needs_rotation = [{"type": kt, "reason": "forced", "expiry": None}
                          for kt in KEY_TYPES]

    # Rotálás ha kell
    if needs_rotation:
        log.info("%d key(s) need rotation: %s",
                 len(needs_rotation),
                 ", ".join(k["type"] for k in needs_rotation))
        success = rotate_keys(needs_rotation, state)
        if success:
            log.info("Rotation completed successfully.")
        else:
            log.error("Rotation completed with errors!")
    else:
        log.info("All keys are within safe threshold, no rotation needed.")

    # Mentés
    save_state(state)

    log.info("=== Daily key rotation check finished ===\n")
    return 0

def run_rotate() -> int:
    """Kényszerített rotáció (minden kulcs)."""
    return run_check(force=True)

def run_status() -> int:
    """Státusz riport."""
    state = load_state()
    print_status(state)
    return 0

def run_init() -> int:
    """Inicializálja a kulcsrendszert első telepítésnél."""
    log.info("=== Initializing SSHd key rotation system ===")

    if not ensure_ca_exists():
        return 1

    ensure_sshd_config_has_certs()

    # Generálj minden kulcsot
    state = load_state()
    needs_rotation = [{"type": kt, "reason": "initial", "expiry": None}
                      for kt in KEY_TYPES]

    success = rotate_keys(needs_rotation, state)
    save_state(state)

    if success:
        log.info("Initialization complete. All keys generated and signed.")
        return 0
    else:
        log.error("Initialization completed with errors.")
        return 1

# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main():
    parser = argparse.ArgumentParser(
        description="A2A Mesh SSHd (port 2230) key rotation automation."
    )
    parser.add_argument(
        "--check", action="store_true",
        help="Daily check: examine key expiry and rotate if within threshold."
    )
    parser.add_argument(
        "--rotate", action="store_true",
        help="Force rotation of all keys immediately."
    )
    parser.add_argument(
        "--status", action="store_true",
        help="Show current key rotation status."
    )
    parser.add_argument(
        "--init", action="store_true",
        help="Initialize the key rotation system (first-time setup)."
    )
    parser.add_argument(
        "--ttl", type=int, default=DEFAULT_KEY_TTL_DAYS,
        help=f"Key TTL in days (default: {DEFAULT_KEY_TTL_DAYS})."
    )
    parser.add_argument(
        "--threshold", type=int, default=ROTATION_THRESHOLD_DAYS,
        help=f"Rotation threshold in days before expiry (default: {ROTATION_THRESHOLD_DAYS})."
    )

    args = parser.parse_args()

    # Override globals if specified
    global DEFAULT_KEY_TTL_DAYS, ROTATION_THRESHOLD_DAYS
    if args.ttl != DEFAULT_KEY_TTL_DAYS:
        DEFAULT_KEY_TTL_DAYS = args.ttl
    if args.threshold != ROTATION_THRESHOLD_DAYS:
        ROTATION_THRESHOLD_DAYS = args.threshold

    if args.init:
        return run_init()
    elif args.check:
        return run_check()
    elif args.rotate:
        return run_rotate()
    elif args.status:
        return run_status()
    else:
        parser.print_help()
        return 1

if __name__ == "__main__":
    sys.exit(main())